for p in (S/'content/editions/issue-28').glob('poem-*.json'):(B/p.name).write_bytes(p.read_bytes())
b=dict(edition=28,status='planned',created_at=now,poems_read=sorted(json.loads(p.read_text())['id'] for p in (S/'content/editions/issue-28').glob('poem-*.json')),direction='February listens to ordinary traces: touch held by a wall, a small offering at the waterline, and grass beside a brook. Close material study, sparse water wash and low living landscape vary density and medium. The mythic ghazal and the historical comparison remain text-led.',items=items,text_led=plain,independent=False)
(B/'batch.json').write_text(json.dumps(b,ensure_ascii=False,indent=2)+'\n');ed=next(x for x in q['editions'] if x['edition']==28);ed.update(status='planned',artworks=[i['id'] for i in items],text_led=[i['poem_id'] for i in plain],batch=str((B/'batch.json').relative_to(R)),direction=b['direction']);q['active_batch']=dict(id='edition-28',owner='current-chat-assistant',started_at=now,status='running');q['updated_at']=now;(K/'queue.json').write_text(json.dumps(q,ensure_ascii=False,indent=2)+'\n')
